#pragma once
int runSimilarity430(){
 juce::ScopedJuceInitialiser_GUI gui;LibraryPreparation::checksPaused=true;std::cout.setf(std::ios::unitbuf);
 auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};
 try{
  auto fixture=LibraryStore::root();auto audioFolder=fixture.getChildFile("Drum examples");audioFolder.createDirectory();
  juce::Array<juce::File> originals;for(auto name:{"similar","not similar"})juce::File("/Users/duncanmaclennan/Desktop").getChildFile(name).findChildFiles(originals,juce::File::findFiles,false,"*.wav");originals.sort();require(originals.size()==10,"ten examples");juce::Array<juce::File> files;for(auto f:originals){auto copy=audioFolder.getChildFile(f.getFileName());require(f.copyFileTo(copy),"copy example fixture");files.add(copy);}
  auto expected=juce::JSON::parse(juce::File::getCurrentWorkingDirectory().getChildFile("work/similarity-study/native-expected.json"));
  char error[512]{};std::unique_ptr<void,decltype(&sg_similarity_destroy)> model(sg_similarity_create(DrumSimilarity::modelFile().getFullPathName().toRawUTF8(),error,sizeof(error)),sg_similarity_destroy);require(model!=nullptr,error);
  std::vector<std::pair<juce::String,DrumSimilarity::Features>> rows;
  juce::var report(new juce::DynamicObject());juce::Array<juce::var> results;double minimum=1;int nearest=0,perfect=0;
  for(auto f:files){auto began=juce::Time::getMillisecondCounterHiRes();auto value=DrumSimilarity::extract(f,model.get(),[]{return false;});int index=-1;auto names=expected["names"];for(int i=0;i<names.size();++i)if(names[i].toString()==f.getFileName())index=i;require(index>=0,"expected file");double dot=0;for(int d=0;d<512;++d)dot+=value.sound[d]*(double)expected["embeddings"][index][d];minimum=std::min(minimum,dot);require(dot>.995,"native embedding parity");std::cout<<f.getFileName()<<": cosine "<<dot<<", "<<juce::Time::getMillisecondCounterHiRes()-began<<" ms\n";rows.emplace_back(f.getFullPathName(),value);}
  for(auto& ref:rows){if(!juce::File(ref.first).getFileName().startsWith("L "))continue;auto scores=DrumSimilarity::rank(ref.second,rows);scores.erase(ref.first);std::vector<std::pair<float,juce::String>> sorted;for(auto& s:scores)sorted.emplace_back(s.second,s.first);std::sort(sorted.begin(),sorted.end());nearest+=juce::File(sorted[0].second).getFileName().startsWith("L ");bool all=true;juce::Array<juce::var> names;for(int i=0;i<5;++i){auto name=juce::File(sorted[i].second).getFileName();all&=name.startsWith("L ");names.add(name);}perfect+=all;juce::var result(new juce::DynamicObject());result.getDynamicObject()->setProperty("reference",juce::File(ref.first).getFileName());result.getDynamicObject()->setProperty("top5",names);results.add(result);}
  require(nearest==6&&perfect>=3,"drum ranking regression");report.getDynamicObject()->setProperty("rankings",results);report.getDynamicObject()->setProperty("minimumCosine",minimum);report.getDynamicObject()->setProperty("nearestCorrect",nearest);report.getDynamicObject()->setProperty("perfectTop5",perfect);fixture.getChildFile("ranking.json").replaceWithText(juce::JSON::toString(report));model.reset();
  auto wait=[](auto predicate){auto until=juce::Time::getMillisecondCounterHiRes()+60000;while(!predicate()&&juce::Time::getMillisecondCounterHiRes()<until){CFRunLoopRunInMode(kCFRunLoopDefaultMode,.002,true);juce::Thread::sleep(2);}return predicate();};
  // Run real 128-frame audio callbacks throughout a cold background preparation.
  struct PlaybackStress {
   std::unique_ptr<Processor> processor;std::atomic<bool> stop{false};std::thread worker;double maximum=0;int callbacks=0,overruns=0,silent=0;
   PlaybackStress(){processor=std::make_unique<Processor>(false);auto source=std::make_shared<AudioData>();source->rate=48000;source->buffer.setSize(1,48000);source->peakAmplitude=.2f;for(int i=0;i<48000;++i)source->buffer.setSample(0,i,.2f*std::sin(i*2*juce::MathConstants<double>::pi*220/48000));processor->audio=source;processor->autoSave=false;processor->normaliseEnabled=false;processor->oneShotMode=true;processor->shotRootNote=60;processor->shotLoop=true;processor->shotLoopStart=0;processor->shotLoopEnd=48000;processor->shotEnvelope={0,0,1,.001f};processor->prepareToPlay(48000,128);processor->triggerShot(60,1);worker=std::thread([this]{pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE,0);juce::AudioBuffer<float> audio(2,128);juce::MidiBuffer midi;auto next=std::chrono::steady_clock::now();while(!stop){double begin=juce::Time::getMillisecondCounterHiRes();processor->processBlock(audio,midi);double ms=juce::Time::getMillisecondCounterHiRes()-begin;maximum=std::max(maximum,ms);overruns+=ms>128000./48000;silent+=audio.getMagnitude(0,128)<1e-7;++callbacks;next+=std::chrono::microseconds(2667);std::this_thread::sleep_until(next);}});}
   void finish(){stop=true;if(worker.joinable())worker.join();}~PlaybackStress(){finish();}
  } playback;
  DrumSimilarity service(fixture);auto begin=juce::Time::getMillisecondCounterHiRes();service.prepare({audioFolder});require(juce::Time::getMillisecondCounterHiRes()-begin<10,"non-blocking prepare request");require(wait([&]{return !service.state().busy;}),"prepare finishes");playback.finish();std::cout<<"48 kHz / 128 samples during cold preparation: "<<playback.callbacks<<" callbacks, max "<<playback.maximum<<" ms, "<<playback.overruns<<" overruns, "<<playback.silent<<" silent blocks\n";require(playback.callbacks>100&&playback.overruns==0&&playback.silent==0,"playback during background similarity inference");auto state=service.state();std::cout<<state.message<<"\n";require(state.completed==10&&state.failed==0,"batch prepares all files");
  service.prepare({audioFolder});require(wait([&]{return !service.state().busy;}),"warm preparation");require(service.state().cached==10,"all cached on second pass");
  auto query=files[0];auto revision=service.state().resultRevision;service.find(query);require(wait([&]{return service.state().resultRevision>revision;}),"query completes");state=service.state();require(state.scores&&state.scores->size()==9&&!state.scores->count(query.getFullPathName()),"reference excluded");
  LibraryStore::addLibraryRoot(audioFolder);Processor processor(false);processor.autoSave=false;{Editor editor(processor);editor.setSize(1400,1150);require(editor.similarity430ForCheck(audioFolder,state.scores,query),"browser sorted results, keyword filtering, clear and audio preservation");}
  // Changed files are invalidated; unrelated metadata does not invalidate cached audio.
  files[1].setLastModificationTime(juce::Time::getCurrentTime()+juce::RelativeTime(2));service.prepare({audioFolder});require(wait([&]{return !service.state().busy;}),"changed file batch");require(service.state().cached==9,"changed audio invalidates only one fingerprint");
  {DrumSimilarity persisted(fixture);persisted.prepare({audioFolder});require(wait([&]{return !persisted.state().busy;}),"reopened cache");require(persisted.state().cached==10,"cache survives service restart");persisted.pause(true);persisted.prepare({audioFolder});persisted.pause(true);require(persisted.state().paused,"pause state");persisted.cancel();require(!persisted.state().busy,"cancel state");}
  std::vector<std::pair<juce::String,DrumSimilarity::Features>> large;large.reserve(100000);for(int i=0;i<100000;++i)large.emplace_back("/synthetic/"+juce::String(i),rows[i%rows.size()].second);begin=juce::Time::getMillisecondCounterHiRes();auto ranked=DrumSimilarity::rank(rows[0].second,large);std::cout<<"100,000 cached sound + dynamics scores: "<<juce::Time::getMillisecondCounterHiRes()-begin<<" ms\n";require(ranked.size()==100000,"large index result");
  // Closing cancels pending work rather than draining the collection.
  auto closing=std::make_unique<DrumSimilarity>(fixture.getChildFile("cancel-cache"));closing->prepare({audioFolder});juce::Thread::sleep(20);begin=juce::Time::getMillisecondCounterHiRes();closing.reset();std::cout<<"Cancel/close during preparation: "<<juce::Time::getMillisecondCounterHiRes()-begin<<" ms\n";require(juce::Time::getMillisecondCounterHiRes()-begin<3000,"prompt shutdown");
  require(checkExtractionPlayback420(),"audio continuity under message-thread contention");
  std::cout<<"Native model parity, rankings "<<nearest<<"/6 nearest and "<<perfect<<"/6 top-five, cold/warm/reopened cache, invalidation, browser filtering/exit, pause/cancel and shutdown passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 4301;}
}
